import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []
    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        if '1' in S:
            results.append("WIN")
        else:
            results.append("LOSE")

    print('\n'.join(results))

if __name__ == "__main__":
    main()
